rules:
- id: "vuln-novnc-ad941fad"
  pattern: |
    document.cookie = $NAME + "=" + $VALUE + $EXPIRES + "; path=/"
  pattern-not: |
    if (document.location.protocol === "https:") {
        $SECURE = "; secure";
    } else {
        $SECURE = "";
    }
    document.cookie = $NAME + "=" + $VALUE + $EXPIRES + "; path=/" + $SECURE;
  languages: ["javascript"]
  message: "Potential cookie security vulnerability. Cookies should be marked as secure when using HTTPS to prevent interception. Ensure that cookies are set with the 'secure' attribute when the connection is secure."
  severity: ERROR
  metadata:
    source-url: github.com/kanaka/noVNC/commit/ad941faddead705cd611921730054767a0b32dcd
    category: security
    cwe: CWE-614
    owasp: A3:2021-Sensitive Data Exposure
    references: 
      - https://owasp.org/www-project-top-ten/2021/A03_Sensitive_Data_Exposure
      - https://developer.mozilla.org/en-US/docs/Web/HTTP/Cookies#security
    technology: javascript
